function gates(targets,pools,traces){return{permissionBitsBound:targets.every(x=>x.permissions),enabledCallbacksBound:targets.every(x=>x.permissions),initializationEventsComplete:pools.initializationEventsComplete,exactPoolKeysBound:pools.exactPoolKeysBound,beforeSwapPoolManagerInvocationTraceBound:traces.some(x=>x.findings.beforeSwapPoolManagerInvocationTraceBound)?true:null,erc4626SelectorsPresent:targets.some(x=>x.bytecodeAnalysis.erc4626SelectorsPresent),erc4626CallsObservedInManagementFlow:traces.some(x=>x.findings.managementFlowErc4626CallsObserved)?true:null,erc4626ReachableFromBeforeSwap:null,poolManagerSenderGateBound:null,attackerCreatedPoolReachabilityProven:null,deployedValueMovingTargetProof:null,exactReceiverValueFlowProven:null,exactEconomicsComputed:null,forkJustified:null,routePositive:false,executableNow:false,signedActionJustified:false};}
function blockers(g){const b=[];if(g.initializationEventsComplete!==true)b.push("Lifetime Initialize coverage is incomplete or undecodable.");if(g.beforeSwapPoolManagerInvocationTraceBound!==true)b.push("Observed transactions do not bind a PoolManager -> beforeSwap invocation.");if(g.erc4626ReachableFromBeforeSwap!==true)b.push("Correct-entry CFG remains partial; ERC4626 reachability from beforeSwap is unproven.");if(g.poolManagerSenderGateBound!==true)b.push("PoolManager sender gate is not source- or bytecode-bound.");b.push("Attacker-created pool reachability, deployed value-moving target, exact receiver flow, and positive economics remain unproven.");return b;}
function report(raw){const p=raw.poolEvidence.counts,v=raw.chain.providerValidation;return`# DEX hook current reachability\n\n**Classification:** ${raw.classification}\n\n**Run:** \`${raw.runId}\` at fixed Ethereum block **${raw.chain.currentBlock}** (\`${raw.chain.currentBlockHash}\`).\n\n## Validated provider sets\n\nOnly inventory entries explicitly labeled Ethereum were parsed; public Ethereum fallbacks were appended. ${v.totalCandidateCount} candidates were independently checked. Baseline validated=${v.baselineValidatedCount}; capability counts: ${Object.entries(v.capabilitySets).map(([k,x])=>`${k}=${x.validatedCount}`).join(", ")}. Pin recheck=${raw.chain.pinRecheck.allMatched}. No endpoint value was emitted.\n\n## Permissions and canonical definitions\n\n| Hook | mask | callbacks | return conventions |\n|---|---:|---|---|\n${raw.targets.map(x=>`| ${x.id} | \`${x.permissions.canonicalLow14Mask}\` | ${x.permissions.enabledCallbacks.join(", ")} | ${x.permissions.enabledReturnConventions.join(", ")} |`).join("\n")}\n\nH2 is **0x0088**, not 0x1088. Canonical permission/event definitions are embedded and hash-bound as \`${raw.definitions.hash}\`. \`reports/raw/fast/uniswap-v4-hooks.json\` is demoted legacy/misclassified and was not read as proof.\n\n## Lifetime pools\n\nPoolManager first code: ${raw.poolManager.firstCodeBlock}. Lifetime Initialize coverage starts there and ends at the fixed head.\n\n| Hook | lifetime | pre-deployment | post-deployment | swaps | liquidity | donate |\n|---|---:|---:|---:|---:|---:|---:|\n${TARGETS.map(t=>`| ${t.id} | ${p[t.id].lifetime} | ${p[t.id].preDeployment} | ${p[t.id].postDeployment} | ${p[t.id].activity.swap} | ${p[t.id].activity.modifyLiquidity} | ${p[t.id].activity.donate} |`).join("\n")}\n\nInitialize complete=${raw.gates.initializationEventsComplete}; exact keys=${raw.gates.exactPoolKeysBound}; activity complete=${raw.poolEvidence.activityEventsComplete}. Compact range response hashes and matching raw-log hashes are in the raw artifact.\n\n## Dispatcher, CFG, and traces\n\n${raw.targets.map(x=>`- ${x.id}: beforeSwap entry=\`0x${x.bytecodeAnalysis.entryAssertions.beforeSwap.actualPc.toString(16)}\`; afterInitialize entry=\`0x${x.bytecodeAnalysis.entryAssertions.afterInitialize.actualPc.toString(16)}\`; CFG=${x.bytecodeAnalysis.beforeSwapCfg.graphRecoveryStatus}; unresolved=${x.bytecodeAnalysis.beforeSwapCfg.unresolvedDynamicEdges.length}; reachability=null.`).join("\n")}\n\n${raw.observedTransactions.map(x=>`- ${x.targetId}: PoolManager calls=${x.findings.poolManagerCallsToTarget.length}; canonical enabled hook callbacks=${x.findings.canonicalEnabledHookCallbacks.length}; unlockCallback=${x.findings.unlockCallbacks.length}; beforeSwap=${x.findings.beforeSwapPoolManagerInvocationTraceBound}; H2 asset STATICCALLs=${x.findings.h2Staticcalls.length}.`).join("\n")}\n\nH1's observed PoolManager→hook call is \`unlockCallback(bytes)\` management flow, not a canonical v4 hook callback. H2 has no PoolManager→target call.\n\n## Gates\n\n${Object.entries(raw.gates).map(([k,v])=>`- ${k}: ${v===null?"null":v}`).join("\n")}\n\n## Blockers\n\n${raw.blockers.map(x=>`- ${x}`).join("\n")}\n\nNo signing, submission, mutation, or live exploit execution occurred. Detached hashes are in \`reports/raw/fast/dex-hook-current-reachability.manifest.json\`.\n`;}
function handoff(raw){const p=raw.poolEvidence.counts;return`# Coordinator handoff — DEX hook current reachability\n\n- Run: \`${raw.runId}\`; fixed block ${raw.chain.currentBlock} / \`${raw.chain.currentBlockHash}\`.\n- Validated providers: ${Object.entries(raw.chain.providerValidation.capabilitySets).map(([k,x])=>`${k}=${x.validatedCount}`).join(", ")}; values withheld.\n- Lifetime pools: H1=${p.h1.lifetime} (${p.h1.preDeployment} pre/${p.h1.postDeployment} post), H2=${p.h2.lifetime} (${p.h2.preDeployment} pre/${p.h2.postDeployment} post).\n- Activity: H1 swaps=${p.h1.activity.swap}, liquidity=${p.h1.activity.modifyLiquidity}, donate=${p.h1.activity.donate}; H2 swaps=${p.h2.activity.swap}, liquidity=${p.h2.activity.modifyLiquidity}, donate=${p.h2.activity.donate}.\n- Entries: H1 beforeSwap=0x13da/afterInitialize=0x10b4; H2 beforeSwap=0x1342/afterInitialize=0x11fa.\n- Trace correction: H1 PoolManager call is unlockCallback management flow; canonical hook callbacks=0. H2 PoolManager calls=0.\n- routePositive=false; executableNow=false; signedActionJustified=false; forkJustified=null.\n- Blockers: ${raw.blockers.join(" ")}\n`;}
function evidence(file){const b=fs.readFileSync(file);return{file:rel(file),sha256:sha256(b),bytes:b.length};}function sourceFiles(dir){const out=[];for(const e of fs.readdirSync(dir,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))){const p=path.join(dir,e.name);if(e.isDirectory())out.push(...sourceFiles(p));else out.push(p);}return out;}
function manifest(runId,marker){const files={scanner:evidence(__filename),sources:sourceFiles(SRC).map(evidence),raw:evidence(RAW),report:evidence(REPORT),handoff:evidence(HANDOFF)};writeJson(MANIFEST,{schemaVersion:2,runId,generationId:runId,fixedGenerationDateMarker:marker,detached:true,selfExcluded:true,files,verification:{hashAlgorithm:"sha256",allFilesExist:true,sizesBound:true}});return readJson(MANIFEST);}

let STAGE="startup";
async function main(){const prior=!REFRESH?readJson(RAW):null;STAGE="candidate-parse";const set=candidates();STAGE="pin";const pin=await establishPin(set.rows,prior);STAGE="provider-validation";const validation=await validateRows(set,pin),pool=new Pool(set,pin,validation),definitions={schemaVersion:1,permissionFlags:FLAGS.map(([name,bit,isCallback])=>({name,bit,isCallback})),hookAbi:HOOK_ABI,eventAbi:EVENT_DEFS,selectors:SELECTORS,legacyArtifact:{path:"reports/raw/fast/uniswap-v4-hooks.json",status:"demoted-legacy-misclassified",usedAsProof:false}};definitions.hash=hashCanonical(definitions);writeJson(path.join(SRC,"canonical-definitions.json"),definitions);STAGE="targets";const targets=[];for(const t of TARGETS)targets.push(await collectTarget(pool,t,definitions.hash));STAGE="poolmanager-boundary";const pmBoundary=await firstCodeBlock(pool,PM);STAGE="lifetime-logs";const poolEvidence=await lifetimePools(pool,pmBoundary.blockNumber);STAGE="currencies";const currencies=await currencyState(pool,poolEvidence);STAGE="observed-traces";const traces=await observed(pool),g=gates(targets,poolEvidence,traces);STAGE="pin-recheck";const pinRecheck=await pool.recheckPin(),providerValidation=pool.evidence(),block=await pool.call("core","eth_getBlockByNumber",[hex(pin.number),false]);
  providerValidation.metricsSnapshotPolicy="retain prior operation counters only after same-pin current validation-set fingerprint match";
  if(prior?.chain?.currentBlock===pin.number&&prior?.chain?.currentBlockHash===pin.hash&&prior?.chain?.providerValidation?.validationFingerprint===providerValidation.validationFingerprint)providerValidation.operations=prior.chain.providerValidation.operations;
  await pool.recheckPin();
  const marker=new Date(num(block.timestamp)*1000).toISOString(),core={schemaVersion:3,scanner:SCANNER,classification:CLASSIFICATION,definitions,chain:{chainId:1,currentBlock:pin.number,currentBlockHash:pin.hash,currentBlockTimestamp:num(block.timestamp),providerValidation,pinRecheck},poolManager:{address:PM,firstCodeBlock:pmBoundary.blockNumber,firstCodeEvidence:pmBoundary},targets,poolEvidence,currencies,observedTransactions:traces,gates:g,safety:{readOnly:true,ethereumLabelOnlyInventory:true,providerValuesEmitted:false,secretsPersisted:false,signing:false,submission:false,stateMutation:false}};core.blockers=blockers(g);const runId=`dex-hook-current-${hashCanonical(core).slice(0,20)}`,raw={generatedAt:marker,runId,...core};writeJson(RAW,raw);atomic(REPORT,report(raw));atomic(HANDOFF,handoff(raw));const m=manifest(runId,marker),rows=[m.files.scanner,...m.files.sources,m.files.raw,m.files.report,m.files.handoff];if(!rows.every(x=>{const b=fs.readFileSync(path.join(ROOT,x.file));return b.length===x.bytes&&sha256(b)===x.sha256;}))throw new Error("detached manifest verification failed");if(!QUIET)console.log(JSON.stringify({ok:true,runId,block:pin.number,validated:Object.fromEntries(Object.entries(providerValidation.capabilitySets).map(([k,v])=>[k,v.validatedCount])),counts:poolEvidence.counts,entries:Object.fromEntries(targets.map(x=>[x.id,x.bytecodeAnalysis.entryAssertions])),traceCategories:traces.map(x=>({id:x.targetId,poolManager:x.findings.poolManagerCallsToTarget.length,canonical:x.findings.canonicalEnabledHookCallbacks.length,unlock:x.findings.unlockCallbacks.length})),gates:g,rawBytes:fs.statSync(RAW).size,manifest:rel(MANIFEST)},null,2));}
main().catch(e=>{const detail=STAGE==="pin"?String(e.message).replace(/https?:\/\/\S+/gi,"[endpoint]"):errClass(e);console.error(`scan failed at ${STAGE}: ${detail}`);process.exitCode=1;});
